return useQuery({
  queryKey: [...POKEMON_QUERY_KEY, trainerId],
  queryFn: () => fetchPokemon(trainerId),
  select: (pokemon) => pokemon.filter((entry) => hasType(entry, type)),
  placeholderData: keepPreviousData,
})

{pokemon && pokemon.length === 0 && <p>No Pokemon match these filters.</p>}
{pokemon && pokemon.length > 0 && (
  <ul>
    {pokemon.map((entry) => (
      <li key={entry.id}>
        {entry.name} Lv. {entry.level} {formatTypes(entry)}
      </li>
    ))}
  </ul>
)}
